}

# Markdown include shortcut for content pages. The md-page class constrains
# images to the card width (see custom.css) — markdown-rendered <img> tags
# carry no CSS class, and cards clip overflow.
# Render from text, not from the file path: given a path, markdown::mark()
# (>= 2.0) rewrites the source file in place when it runs under R CMD check,
# and the installed package library may be read-only (CRAN mounts it so).
# Given text it renders the same HTML without writing anything; mark() is
# run from markdown/ so relative image references still resolve (and embed)
# exactly as they do for file input.
md_page <- function(file) {
  path <- file.path("markdown", file)
  lines <- readLines(path, encoding = "UTF-8", warn = FALSE)
  owd <- setwd(dirname(path))
  html <- tryCatch(markdown::mark(text = lines, output = NULL), finally = setwd(owd))
  Encoding(html) <- "UTF-8"
  div(class = "p-2 md-page", HTML(html))
}

# Compact HTML table for small teaching examples (statistics pages).
teach_table <- function(df) {
  tags$table(
    class = "table table-striped table-sm-tight w-auto",
    tags$thead(tags$tr(lapply(names(df), tags$th))),
    tags$tbody(
      lapply(seq_len(nrow(df)), function(i) {
        tags$tr(lapply(df[i, ], function(x) tags$td(format(x))))
      })
    )
  )
}

# Copy-to-clipboard button for a <pre>/<div> element holding text content.
copy_button <- function(target_id, label = "Copy") {
  tags$button(
    class = "btn btn-sm btn-outline-primary mb-2",
    onclick = sprintf(
      "navigator.clipboard.writeText(document.getElementById('%s').innerText).then(() => { this.innerText = 'Copied!'; setTimeout(() => this.innerText = '%s', 1500); });",
      target_id, label
    ),
    label
  )
}

catalogue <- utils::read.delim("www/i18n/zh.tsv", encoding = "UTF-8", sep = "\t",
  quote = "", comment.char = "", colClasses = "character", na.strings = NULL,
  stringsAsFactors = FALSE)
stopifnot(identical(names(catalogue), c("en", "zh")), !anyDuplicated(catalogue$en))
cata_dictionary <- stats::setNames(catalogue$zh, catalogue$en)

cata_session_language <- function() {
  session <- shiny::getDefaultReactiveDomain()
  if (is.null(session)) return("en")
  selected <- session$rootScope()$input$cata_language
  if (identical(selected, "zh")) "zh" else "en"
}

cata_label <- function(text, language = cata_session_language()) {
  if (!identical(language, "zh")) return(text)
  translated <- unname(cata_dictionary[text])
  ifelse(is.na(translated), text, translated)
}

# Used only for fixed statistics lessons, never for user-supplied plot labels.
cata_teaching_labs <- function(...) {
  do.call(ggplot2::labs, lapply(list(...), cata_label))
}

server <- function(input, output, session) {
  # In the packaged desktop build the launcher sets CATA_DESKTOP=1: closing
  # the browser window then also stops the R process. On a Shiny server this
  # must not happen, so it is opt-in.
  if (Sys.getenv("CATA_DESKTOP") == "1") {
    session$onSessionEnded(function() {
      stopApp()
    })
  }

  # Datasets -----------------------------------------------------------------

  df1 <- reactiveVal()
  df2 <- reactiveVal()

  cleaningServer("ds1", df1, demo_file = "data/cat-dirty-data.xlsx")
  cleaningServer("ds2", df2, demo_file = "data/cat-dirty-data2.xlsx")

  # Merging ------------------------------------------------------------------

  source("R/server-merging.R", local = TRUE, encoding = "UTF-8")

  observe({
    df <- df1()
    req(df)
    current_selected <- input$key1
    keep_selected <- intersect(current_selected, names(df))
    updateSelectizeInput(session, "key1", choices = names(df), selected = keep_selected)
  })
  observe({
    df <- df2()
    req(df)
    current_selected <- input$key2
    keep_selected <- intersect(current_selected, names(df))
    updateSelectizeInput(session, "key2", choices = names(df), selected = keep_selected)
  })

  df_merged_applied <- reactiveVal(NULL)
  observeEvent(input$apply_merge, {
    df_merged_applied(df_merged())
    updateRadioButtons(session, "vis_dataset", selected = "merged")
  })

  # The working dataset for visualization, chosen in the Visualize sidebar.
  df0 <- reactive({
    req(input$vis_dataset)
    switch(
      input$vis_dataset,
      ds1 = df1(),
      ds2 = df2(),
      merged = df_merged_applied()
    )
  })

  output$df1_pre_merge <- renderDT(
    {
      req(df1())
      catatable(df1())
    },
    server = FALSE
  )
  output$df2_pre_merge <- renderDT(
    {
      req(df2())
      catatable(df2())
    },
    server = FALSE
  )
  output$df_merged <- renderDT(
    {
      req(input$action_merge)
      req(df_merged())
      catatable(df_merged())
    },
    server = FALSE
  )

  # Visualization --------------------------------------------------------------

  # Variable-selector updates live in server-visualization.R (vis_var_specs).
  source("R/server-visualization.R", local = TRUE, encoding = "UTF-8")

  ## Chart outputs -------------------------------------------------------------

  output$df_vis <- renderDT(
    {
      validate_vis_data()
      catatable(df0())
    },
    server = FALSE
  )

  output$p_bar_col <- renderPlotly({
    validate_vis_data()
    req(input$bar_x)
    cata_plotly(p_bar_col())
  })

  output$p_hist <- renderPlotly({
    validate_vis_data()
    req(input$hist_x)
    cata_plotly(p_hist())
  })

  output$p_den <- renderPlotly({
    validate_vis_data()
    req(input$den_x)
    cata_plotly(p_den())
  })

  output$p_pie <- renderPlotly({
    validate_vis_data()
    req(input$pie_x)
    plotly_tidy_toolbar(p_pie())
  })

  output$p_line <- renderPlotly({
    validate_vis_data()
    req(input$line_x)
    req(input$line_y)
    cata_plotly(p_line())
  })

  output$p_point <- renderPlotly({
    validate_vis_data()
    req(input$point_x)
    req(input$point_y)
    cata_plotly(p_point())
  })

  output$p_box <- renderPlotly({
    validate_vis_data()
    req(input$box_x)
    req(input$box_y)
    cata_plotly(p_box())
  })

  # Statistics pages ------------------------------------------------------------

  source("R/server-stats.R", local = TRUE, encoding = "UTF-8")

  # Quiz -------------------------------------------------------------------------

  quizServer("quiz", quiz_questions)

  if (cata_workshop) {
    whyServer("why")
    workflowServer("workflow", reactive(list(ds1 = df1(), ds2 = df2(), merged = df_merged_applied())))
    miServer("mi")
    publicHealthServer("public")
  }
}

# Per-dataset module: import, missing data, outliers, and text cleaning.
# One cleaningServer() instance per dataset replaces the duplicated df1/df2
