# ---- Server -----------------------------------------------------------------

# data_rv: a reactiveVal holding the dataset; the module reads it and writes
# cleaned versions back, so merging/visualization at the top level see updates.
cleaningServer <- function(id, data_rv, demo_file = NULL) {
  moduleServer(id, function(input, output, session) {
    # Untouched copy of the last import, for the reset buttons.
    raw_rv <- reactiveVal(NULL)

    # Friendly empty state shown in place of tables and plots before import.
    need_data <- function() {
      validate(need(
        data_rv(),
        cata_label("No data yet — upload a file or load the example data on the Import page.")
      ))
    }

    # Import -------------------------------------------------------------
    observeEvent(input$file, {
      tryCatch(
        {
          df <- safe_import_data(input$file$datapath, input$file$name)
          raw_rv(df)
          data_rv(df)
        },
        error = function(e) {
          showNotification(conditionMessage(e), type = "error")
        }
      )
    })

    observeEvent(input$demo, {
      req(demo_file)
      tryCatch(
        {
          df <- safe_import_data(demo_file)
          raw_rv(df)
          data_rv(df)
          showNotification(
            paste("Example data loaded:", basename(demo_file)),
            type = "message"
          )
        },
        error = function(e) {
          showNotification(conditionMessage(e), type = "error")
        }
      )
    })

    # One reset button per cleaning page, all with the same behaviour.
    walk(
      c("reset_import", "reset_missing", "reset_outlier", "reset_text"),
      function(.id) {
        observeEvent(input[[.id]], {
          req(raw_rv())
          data_rv(raw_rv())
          showNotification(
            "Dataset restored to the original import.",
            type = "message"
          )
        })
      }
    )

    output$datatable <- renderDT(
      {
        need_data()
        catatable(data_rv())
      },
      server = FALSE
    )
    output$glimpse <- renderPrint({
      req(data_rv())
      old_width <- getOption("width")
      old_twidth <- getOption("tibble.width")
      options(width = 150, tibble.width = Inf)
      on.exit({
        options(width = old_width)
        options(tibble.width = old_twidth)
      })
      print(skim(data_rv()))
    })

    # Missing data ---------------------------------------------------------
    observe({
      df <- data_rv()
      req(df, any_miss(df))
      updateCheckboxGroupInput(
        session,
        "missing_variable",
        choices = c("All", miss_var_which(df)),
        selected = NULL
      )
    })

    missing_variable <- reactive({
      req(data_rv())
      if (is.null(input$missing_variable)) {
        character(0)
      } else if (any(input$missing_variable == "All")) {
        miss_var_which(data_rv())
      } else {
        intersect(input$missing_variable, names(data_rv()))
      }
    })

    df_drop_na <- reactive({
      req(input$deal_missing_method == "drop_na")
      if (length(missing_variable()) == 0) {
        data_rv()
      } else {
        drop_na(data_rv(), missing_variable())
      }
    })

    df_fill <- reactive({
      req(input$deal_missing_method == "fill")
      req(input$missing_params)
      if (length(missing_variable()) == 0) {
        data_rv()
      } else {
        fill(data_rv(), missing_variable(), .direction = input$missing_params)
      }
    })

    df_mean <- reactive({
      req(input$deal_missing_method == "mean")
      impute_mean_vars(data_rv(), missing_variable())
    })

    df_median <- reactive({
      req(input$deal_missing_method == "median")
      impute_median_vars(data_rv(), missing_variable())
    })

    df_knn <- reactive({
      req(input$deal_missing_method == "knn")
      if (length(missing_variable()) == 0 || all_complete(data_rv())) {
        data_rv()
      } else {
        validate(need(FALSE,
                      "kNN imputation is available in the R app."))
        stop("kNN imputation is available in the R app.")
      }
    })

    df_no_missing <- reactive({
      req(data_rv())
      req(input$deal_missing_method)
      switch(
        input$deal_missing_method,
        "drop_na" = df_drop_na(),
        "fill" = df_fill(),
        "mean" = df_mean(),
        "median" = df_median(),
        "knn" = df_knn()
      )
    })

    observeEvent(input$apply_missing, {
      if (!is.null(input$deal_missing_method)) {
        data_rv(df_no_missing())
      }
    })

    # has_missing() prints its own "No dataset is available." message, so no
    # req() here.
    output$has_missing <- renderPrint({
      has_missing(data_rv())
    })

    need_missing <- function() {
      need_data()
      validate(need(
        any_miss(data_rv()),
        cata_label("No missing values in this dataset. 🎉")
      ))
    }

    output$p_vis_miss <- renderPlotly({
      need_missing()
      cata_plotly(vis_miss(data_rv()))
    })
    output$p_aggr <- renderPlot({
      need_missing()
      mice::md.pattern(as.data.frame(data_rv()), rotate.names = TRUE)
    })
    output$p_gg_miss_var <- renderPlotly({
      need_missing()
      cata_plotly(gg_miss_var(data_rv()))
    })
    output$p_gg_miss_case <- renderPlotly({
      need_missing()
      cata_plotly(gg_miss_case(data_rv()))
    })
    output$df_no_missing <- renderDT(
      {
        need_data()
        catatable(df_no_missing())
      },
      server = FALSE
    )

    # Outliers -------------------------------------------------------------
    observe({
      df <- data_rv()
      req(df)
      req(any_outlier(df))
      updateCheckboxGroupInput(
        session,
        "outlier_variable",
        choices = c("All", recognize_outlier_variable(df)),
        selected = NULL
      )
    })

    output$missing_alert <- renderUI({
      df <- data_rv()
      req(df)
      if (any_miss(df)) {
        div(
          class = "alert alert-warning py-2",
          icon("triangle-exclamation"),
          "Please deal with missing values first."
        )
      }
    })

    outlier_variable <- reactive({
      req(data_rv())
      if (is.null(input$outlier_variable)) {
        character(0)
      } else if (any(input$outlier_variable == "All")) {
        recognize_outlier_variable(data_rv())
      } else {
        intersect(input$outlier_variable, recognize_outlier_variable(data_rv()))
      }
    })

    df_remove <- reactive({
      if (length(outlier_variable()) == 0) {
        data_rv()
      } else {
        keep <- Reduce(`&`, lapply(data_rv()[outlier_variable()], recognize_outlier))
        data_rv()[keep, , drop = FALSE]
      }
    })

    df_winsorize <- reactive({
      if (length(outlier_variable()) == 0) {
        data_rv()
      } else {
        data_rv() %>%
          mutate(across(outlier_variable(), winsorize))
      }
    })

    df_no_outlier <- reactive({
      req(data_rv())
      req(input$deal_outlier_method)
      switch(
        input$deal_outlier_method,
        "remove" = df_remove(),
        "winsorize" = df_winsorize()
      )
    })

    observeEvent(input$apply_outlier, {
      if (!is.null(input$deal_outlier_method)) {
        data_rv(df_no_outlier())
      }
    })

    df_long <- reactive({
      df_num <- data_rv() %>%
        select(where(is.numeric))
      validate(need(ncol(df_num) > 0, cata_label("No numeric variables are available.")))
      df_num %>%
        mutate(.id = seq_len(nrow(.))) %>%
        pivot_longer(-.id, names_to = "name", values_to = "value", names_transform = fct) %>%
        # Boxplots ignore missing values anyway; dropping them here keeps the
        # console free of "removed n rows" warnings while data is being cleaned.
        filter(!is.na(value))
    })

    output$p_outlier <- renderPlotly({
      need_data()
      p <- ggplot(df_long(), aes(name, value)) +
        geom_boxplot() +
        labs(x = "", y = "")
      cata_plotly(p)
    })
    output$df_no_outlier <- renderDT(
      {
        need_data()
        catatable(df_no_outlier())
      },
      server = FALSE
    )

    # Text cleaning ----------------------------------------------------------
    # Only character columns are offered: applying str_to_upper() etc. to a
    # numeric column would silently convert it to text.
    observe({
      df <- data_rv()
      req(df)
      updateSelectizeInput(
        session,
        "text_variable",
        choices = names(select(df, where(is.character))),
        selected = NULL
      )
    })

    df_cleaned_text <- eventReactive(input$show_text, {
      req(data_rv())
      df_tmp <- data_rv()
      vars <- intersect(
        input$text_variable,
        names(select(df_tmp, where(is.character)))
      )
      if (length(vars) > 0) {
        fn <- switch(
          input$text_uppercase,
          "ALL UPPER" = str_to_upper,
          "all lower" = str_to_lower,
          "Like Title" = str_to_title,
          "Like sentence" = str_to_sentence
        )
        df_tmp <- df_tmp %>%
          mutate(across(all_of(vars), fn))
        # Whole-cell replacement by exact match, not regex: trainee input like
        # "N/A (unknown)" must never be interpreted as a pattern.
        if (input$text_replace_from != "") {
          df_tmp <- df_tmp %>%
            mutate(
              across(
                all_of(vars),
                ~ if_else(
                  .x == input$text_replace_from,
                  input$text_replace_to,
                  .x,
                  missing = .x
                )
              )
            )
        }
      }
      df_tmp
    })

    observeEvent(input$apply_text, {
      data_rv(df_cleaned_text())
    })

    output$df_clean_text <- renderDT(
      {
        need_data()
        catatable(df_cleaned_text())
      },
      server = FALSE
    )
  })
}

# Interactive quiz module. Questions come from R/data-quiz.R.

quizUI <- function(id) {
  ns <- NS(id)
  div(
    class = "mx-auto",
    style = "max-width: 960px;",
    card(
      card_header("Choose your topics 🎯"),
      markdown(paste(
        "Every training uses a different mix of modules. Tick the topics",
        "covered in your session and restart the quiz — by default all",
        "topics are included.",
        sep = "\n"
      )),
      uiOutput(ns("topic_ui"))
    ),
    card(
      card_header(
        div(
          class = "d-flex justify-content-between align-items-center",
          span("Test yourself"),
          span(class = "text-muted small", textOutput(ns("score_text"), inline = TRUE))
        )
      ),
      uiOutput(ns("progress_ui")),
      uiOutput(ns("question_ui")),
      uiOutput(ns("feedback_ui")),
      uiOutput(ns("buttons_ui"))
    ),
    card(
      card_header("Final exercise: put it all together"),
      markdown(paste(
        "Use the **SDG 3.8.1** indicator data (download from the Home page) and,",
        "with the help of this dashboard or AI-assisted R coding:",
        "",
        "1. **Descriptive analysis** — summarize the distribution of SDG 3.8.1",
        "   values across WPRO countries; identify the minimum, maximum, mean,",
        "   and median.",
        "2. **Visualize 2021** — create a plot showing the indicator values for",
        "   all WPRO countries in the year 2021.",
        "3. **Trends over time** — group the data by year, calculate the annual",
        "   mean for WPRO countries, and create a time series plot.",
        sep = "\n"
      ))
    )
  )
}

quizServer <- function(id, questions) {
  moduleServer(id, function(input, output, session) {
    all_topics <- unique(vapply(questions, function(q) q$topic, character(1)))

    # Questions in play for this session, filtered by the topic selection.
    active <- reactiveVal(questions)
    n_q <- reactive(length(active()))

    idx <- reactiveVal(1)
    score <- reactiveVal(0)
    answered <- reactiveVal(FALSE)
    submitted_answer <- reactiveVal(NULL)
    finished <- reactiveVal(FALSE)

    current <- reactive(active()[[idx()]])

    reset_quiz <- function() {
      idx(1)
      score(0)
      answered(FALSE)
      submitted_answer(NULL)
      finished(FALSE)
    }

    output$topic_ui <- renderUI({
      ns <- session$ns
      div(
        checkboxGroupInput(
          ns("topics"),
          label = NULL,
          choices = all_topics,
          selected = all_topics,
          inline = TRUE
        ),
        actionButton(
          ns("apply_topics"),
          "Apply topics and restart",
          class = "btn-sm btn-outline-primary"
        )
      )
    })

    observeEvent(input$apply_topics, {
      sel <- input$topics
      if (length(sel) == 0) {
        showNotification("Please keep at least one topic.", type = "warning")
        return()
      }
      active(Filter(function(q) q$topic %in% sel, questions))
      reset_quiz()
      showNotification(
        sprintf("Quiz restarted with %d questions.", n_q()),
        type = "message"
      )
    })

    output$score_text <- renderText({
      sprintf("Score: %d / %d", score(), n_q())
    })

    output$progress_ui <- renderUI({
      done <- idx() - 1 + as.numeric(answered() || finished())
      if (finished()) done <- n_q()
      pct <- round(100 * done / n_q())
      div(
        div(class = "quiz-progress", div(style = paste0("width:", pct, "%;"))),
        div(
          class = "text-muted small mb-2",
          if (finished()) {
            "Quiz completed"
          } else {
            sprintf("Question %d of %d", idx(), n_q())
          }
        )
      )
    })

    output$question_ui <- renderUI({
      ns <- session$ns
      if (finished()) {
        pct <- round(100 * score() / n_q())
        remark <- case_when(
          pct >= 90 ~ "Purr-fect! You are ready to clean data like a pro. 🐱",
          pct >= 70 ~ "Great job — just a few whiskers away from perfect. 🐾",
          pct >= 50 ~ "Good start. Review the Cleaning, Visualize, and AI pages and try again.",
          .default = "Keep practising — the Background tabs on each page will help."
        )
        return(div(
          class = "text-center py-4",
          h3(sprintf("You scored %d out of %d (%d%%)", score(), n_q(), pct)),
          p(class = "lead", remark)
        ))
      }
      q <- current()
      tagList(
        span(class = "badge bg-info quiz-topic-badge", q$topic),
        div(class = "mt-2 mb-2", markdown(q$question)),
        if (!is.null(q$image)) {
          tags$img(src = file.path("picture", q$image), class = "quiz-image")
        },
        div(
          class = if (answered()) "quiz-disabled-options" else NULL,
          radioButtons(
            ns("answer"),
            label = NULL,
            choices = q$choices,
            selected = if (answered()) submitted_answer() else character(0),
            width = "100%"
          )
        )
      )
    })

    output$feedback_ui <- renderUI({
      ns <- session$ns
      req(answered(), !finished())
      q <- current()
      correct <- identical(submitted_answer(), q$answer)
      div(
        div(
          class = if (correct) "alert alert-success" else "alert alert-danger",
          icon(if (correct) "circle-check" else "circle-xmark"),
          strong(if (correct) " Correct!" else paste0(" Not quite. The answer is: ", q$answer))
        ),
        card(
          card_header("Why?"),
          markdown(q$explanation),
          if (!is.null(q$plot)) plotlyOutput(ns("answer_plot"))
        )
      )
    })

    output$answer_plot <- renderPlotly({
      req(answered())
      q <- current()
      req(!is.null(q$plot))
      plotly_tidy_toolbar(q$plot())
    })

    output$buttons_ui <- renderUI({
      ns <- session$ns
      if (finished()) {
        return(div(
          class = "d-flex gap-2 mt-2",
          actionButton(ns("restart"), "Try again", class = "btn-primary")
        ))
      }
      div(
        class = "d-flex gap-2 mt-2",
        if (!answered()) {
          actionButton(ns("submit"), "Submit answer", class = "btn-primary")
        } else {
          actionButton(
            ns("next_q"),
            if (idx() < n_q()) "Next question" else "See my result",
            class = "btn-primary"
          )
        },
        actionButton(ns("restart"), "Restart", class = "btn-outline-secondary")
      )
    })

    observeEvent(input$submit, {
      # Guard against double-clicks: the second click arrives before the
      # re-rendered buttons remove "Submit answer" and would double-count.
      if (answered()) {
        return()
      }
      if (is.null(input$answer)) {
        showNotification("Please choose an answer first.", type = "warning")
        return()
      }
      submitted_answer(input$answer)
      answered(TRUE)
      if (identical(input$answer, current()$answer)) {
        score(score() + 1)
      }
    })

    observeEvent(input$next_q, {
      # Same double-click guard: only advance from an answered question.
      if (!answered() || finished()) {
        return()
      }
      if (idx() < n_q()) {
        idx(idx() + 1)
        answered(FALSE)
        submitted_answer(NULL)
      } else {
        finished(TRUE)
      }
    })

    observeEvent(input$restart, {
      reset_quiz()
    })
  })
}

#' A clear theme for training figures
#' @param base_size Base text size in points.
#' @param style Use the built-in theme or the optional DSIR theme.
#' @return A ggplot2 theme.
#' @export
#' @examples
#' theme_cata()
theme_cata <- function(base_size = 13, style = c("cata", "dsi")) {
  style <- match.arg(style)
  if (style == "dsi") {
    if (!requireNamespace("DSIR", quietly = TRUE)) {
      stop("Install the optional DSIR package to use its theme.", call. = FALSE)
    }
    return(DSIR::theme_dsi(base_size = base_size))
  }
  ggplot2::theme_minimal(base_size = base_size) +
    ggplot2::theme(panel.grid.minor = ggplot2::element_blank(),
                   plot.title.position = "plot", plot.caption.position = "plot",
                   plot.title = ggplot2::element_text(face = "bold"),
                   legend.position = "bottom")
}

#' Create a chart with explicit variable names
#'
#' Returns an editable ggplot object. Bar charts count rows when `y` is NULL;
#' supplying `y` uses already summarised values and requires unique chart
#' keys. Lines also require one value per x/group/facet. Charts omit rows
#' missing a required measurement and report that count in the caption.
#' Missing categories in comparison charts are labelled explicitly.
#' @param data A data frame.
#' @param type Chart type: bar, histogram, density, line, scatter, box, dot,
#'   heatmap, dumbbell, forest, or cascade.
#' @param x,y Names of axis variables. `y` is optional only for a count bar,
#'   histogram, or density plot. For a forest plot, x contains term labels.
#' @param group,facet Optional grouping and faceting variable names.
#' @param value Numeric fill variable for a heatmap.
#' @param yend Second numeric value for a dumbbell chart.
#' @param lower,upper Numeric confidence-limit columns for a forest plot.
#' @param title,subtitle,caption Plot text.
#' @param xlab,ylab Optional axis labels, including units where appropriate.
#' @param sort Sort a single-series bar/dot/dumbbell by its value.
#' @param percent Whether values are percentages on a 0 to 100 scale.
#' @param bins Number of histogram bins.
#' @param style Built-in `"cata"` or optional `"dsi"` theme.
#' @param log_scale Use a logarithmic estimate axis for a forest plot.
#' @param reference Reference value for a forest plot (1 for an odds ratio).
#' @return A ggplot object with a `cata_rows` attribute describing input,
#'   plotted, and omitted rows.
#' @importFrom rlang .data
#' @export
#' @examples
#' d <- data.frame(district = c("A", "B"), percent = c(75, 68))
#' cata_plot(d, "dot", "district", "percent", percent = TRUE)
cata_plot <- function(data, type = "bar", x, y = NULL, group = NULL,
                      facet = NULL, value = NULL, yend = NULL, lower = NULL,
                      upper = NULL, title = NULL, subtitle = NULL, caption = NULL,
                      xlab = NULL, ylab = NULL, sort = FALSE, percent = FALSE,
                      bins = 10, style = "cata", log_scale = FALSE, reference = 1) {
  type <- match.arg(type, c("bar", "histogram", "density", "line", "scatter",
                            "box", "dot", "heatmap", "dumbbell", "forest", "cascade"))
  if (!is.null(group) && type %in% c("heatmap", "dumbbell", "cascade")) {
    stop("Use facets to compare groups in a heatmap, dumbbell or cascade chart.", call. = FALSE)
  }
  mappings <- list(x = x, y = y, group = group, facet = facet, value = value,
                   yend = yend, lower = lower, upper = upper)
  present <- mappings[!vapply(mappings, is.null, logical(1))]
  if (any(lengths(present) != 1L)) stop("Choose one column for each mapping.", call. = FALSE)
  cata_assert_columns(data, unique(unlist(present, use.names = FALSE)))
  if (is.null(y) && !type %in% c("bar", "histogram", "density")) {
    stop("This chart needs a y variable.", call. = FALSE)
  }
  if (type == "heatmap" && is.null(value)) stop("Select a numeric heatmap value.", call. = FALSE)
  if (type == "dumbbell" && is.null(yend)) stop("Select both values for a dumbbell.", call. = FALSE)
  if (type == "forest" && (is.null(lower) || is.null(upper))) stop("Select both confidence limits.", call. = FALSE)
  numeric.columns <- unique(c(if (type %in% c("histogram", "density", "scatter")) x,
    if (type != "heatmap") y, value, yend, lower, upper))
  if (length(numeric.columns)) cata_assert_columns(data, numeric.columns, numeric = TRUE)
  plot.data <- as.data.frame(data[unlist(present, use.names = FALSE)], check.names = FALSE)
  names(plot.data) <- names(present)
  if (type %in% c("bar", "box", "dot", "dumbbell", "forest", "cascade") && anyNA(plot.data$x)) {
    labels <- as.character(plot.data$x)
    missing.label <- "(Missing)"
    while (missing.label %in% labels) missing.label <- paste0(missing.label, "*")
    labels[is.na(labels)] <- missing.label
    plot.data$x <- labels
  }
  needed <- setdiff(names(plot.data), c("group", "facet"))
  keep <- stats::complete.cases(plot.data[needed])
  for (column in intersect(names(plot.data), names(present)[vapply(present, function(z) z %in% numeric.columns, logical(1))])) {
    keep <- keep & is.finite(plot.data[[column]])
  }
  plot.data <- plot.data[keep, , drop = FALSE]
  if (!nrow(plot.data)) stop("No usable rows for the selected chart.", call. = FALSE)
  for (column in intersect(c("group", "facet"), names(plot.data))) {
    plot.data[[column]] <- factor(ifelse(is.na(plot.data[[column]]), "(Missing)", as.character(plot.data[[column]])))
  }
  if (!is.null(group) && length(unique(plot.data$group)) > 8) {
    warning("More than eight groups: consider faceting or showing a subset.", call. = FALSE)
  }
  keys <- intersect(c("x", "group", "facet"), names(plot.data))
  if ((type %in% c("line", "dot", "dumbbell", "forest", "cascade") ||
       (type == "bar" && !is.null(y))) && anyDuplicated(plot.data[keys])) {
    stop("Multiple rows share a chart key. Summarise first or choose a grouping variable.", call. = FALSE)
  }
  if (type == "heatmap" && anyDuplicated(plot.data[intersect(c("x", "y", "facet"), names(plot.data))])) {
    stop("A heatmap needs one value per x/y/facet combination.", call. = FALSE)
  }
  if (type == "line" && !(is.numeric(plot.data$x) || inherits(plot.data$x, "Date") ||
                          inherits(plot.data$x, "POSIXt") || is.ordered(plot.data$x))) {
    stop("Use numeric, date, or explicitly ordered x values for a line chart.", call. = FALSE)
  }
  if (type %in% c("histogram", "density") &&
      (length(bins) != 1L || !is.finite(bins) || bins < 1 || bins != as.integer(bins))) {
    stop("'bins' must be a positive integer.", call. = FALSE)
  }
  if (type == "density" && length(unique(plot.data$x)) < 2L) {
    stop("Density estimation needs at least two distinct observations.", call. = FALSE)
  }
  if (percent && type %in% c("histogram", "density", "scatter", "box", "heatmap", "forest")) {
    stop("Percentage scaling is supported for bar, line, dot, dumbbell and cascade charts.", call. = FALSE)
  }
  if (percent && (is.null(y) || any(plot.data$y < 0 | plot.data$y > 100) ||
                 (!is.null(yend) && any(plot.data$yend < 0 | plot.data$yend > 100)))) {
    stop("Percentages must be supplied as values between 0 and 100.", call. = FALSE)
  }
  if (type == "forest") {
    if (any(plot.data$lower > plot.data$y | plot.data$upper < plot.data$y)) {
      stop("Each estimate must lie within its confidence limits.", call. = FALSE)
    }
    if (length(reference) != 1 || !is.finite(reference)) stop("Supply a finite reference value.", call. = FALSE)
    if (log_scale && (any(plot.data$lower <= 0) || reference <= 0)) {
      stop("Logarithmic forest plots require positive estimates, bounds and reference.", call. = FALSE)
    }
  }
  if (sort && is.null(group) && type %in% c("bar", "dot", "dumbbell") && !is.null(y)) {
    ordered <- unique(as.character(plot.data$x[order(plot.data$y)]))
    plot.data$x <- factor(plot.data$x, levels = ordered)
  } else if (type %in% c("box", "dot", "dumbbell", "forest", "cascade")) {
    plot.data$x <- factor(plot.data$x, levels = unique(as.character(plot.data$x)))
  }
  p <- ggplot2::ggplot(plot.data, ggplot2::aes(x = .data$x))
  if (!is.null(y)) p <- p + ggplot2::aes(y = .data$y)
  if (!is.null(group)) p <- p + ggplot2::aes(colour = .data$group, fill = .data$group, group = .data$group)
  blue <- "#0072B2"
  if (type == "bar") {
    p <- if (is.null(y)) p + ggplot2::geom_bar(position = "dodge", colour = NA) else p + ggplot2::geom_col(position = "dodge", colour = NA)
  } else if (type == "histogram") {
    p <- p + ggplot2::geom_histogram(bins = bins, position = "identity", alpha = .65, colour = "white")
  } else if (type == "density") {
    p <- p + ggplot2::geom_density(fill = NA, linewidth = .8)
  } else if (type == "line") {
    if (is.null(group)) p <- p + ggplot2::aes(group = 1)
    p <- p + ggplot2::geom_line(linewidth = .8) + ggplot2::geom_point(size = 2)
  } else if (type == "scatter") {
    p <- p + ggplot2::geom_point(alpha = .75, size = 2.5)
  } else if (type == "box") {
    p <- p + ggplot2::geom_boxplot()
  } else if (type == "dot") {
    p <- p + ggplot2::geom_point(size = 3) + ggplot2::coord_flip()
  } else if (type == "heatmap") {
    p <- p + ggplot2::aes(fill = .data$value) + ggplot2::geom_tile(colour = "white") +
      ggplot2::scale_fill_viridis_c(name = value)
  } else if (type == "dumbbell") {
    p <- p + ggplot2::geom_segment(ggplot2::aes(xend = .data$x, yend = .data$yend), colour = "grey65", linewidth = 1) +
      ggplot2::geom_point(ggplot2::aes(colour = "First"), size = 3) +
      ggplot2::geom_point(ggplot2::aes(y = .data$yend, colour = "Second"), size = 3) +
      ggplot2::scale_colour_manual(values = c(First = "#0072B2", Second = "#D55E00"),
                                   labels = c(First = y, Second = yend), name = NULL) + ggplot2::coord_flip()
  } else if (type == "forest") {
    p <- p + ggplot2::geom_hline(yintercept = reference, linetype = "dashed", colour = "grey60") +
      ggplot2::geom_errorbar(ggplot2::aes(ymin = .data$lower, ymax = .data$upper), width = .18) +
      ggplot2::geom_point(size = 2.8) + ggplot2::coord_flip()
    if (log_scale) p <- p + ggplot2::scale_y_log10()
  } else if (type == "cascade") {
    if (any(plot.data$y < 0)) stop("Cascade counts must be non-negative.", call. = FALSE)
    p <- p + ggplot2::geom_col(fill = blue) + ggplot2::geom_text(ggplot2::aes(label = .data$y), vjust = -.4)
  }
  if (!is.null(group) && !type %in% c("heatmap", "dumbbell")) {
    p <- p + ggplot2::scale_colour_viridis_d(name = group, end = .85) +
      ggplot2::scale_fill_viridis_d(name = group, end = .85)
  }
  if (!is.null(facet)) p <- p + ggplot2::facet_wrap(ggplot2::vars(.data$facet))
  if (percent) p <- p + ggplot2::scale_y_continuous(limits = c(0, 100), labels = scales::label_percent(scale = 1))
  default.y <- if (type == "density") "Density" else if (is.null(y)) "Records" else y
  counts <- list(input = nrow(data), used = nrow(plot.data), omitted = sum(!keep))
  note <- sprintf("Rows used: %s; excluded for missing/non-finite chart values: %s.", counts$used, counts$omitted)
  caption <- paste(c(caption, note), collapse = "\n")
  p <- p + ggplot2::labs(title = title, subtitle = subtitle,
                         x = if (is.null(xlab)) x else xlab,
                         y = if (is.null(ylab)) default.y else ylab, caption = caption) + theme_cata(style = style)
  attr(p, "cata_rows") <- counts
  p
}

